export function tickExpanded(g,world){const root=initExpanded(g);if(root.lastTick===g.turn)return;root.lastTick=g.turn;if(g.turn%3!==0)return;for(const [r,s] of Object.entries(root.realms)){const f=g.factions[r];if(!Object.values(g.provinces).some(p=>controlled(g,r,p)))continue;
 if(s.active){const x=currentExpandedEvent(g,r);if(!x||g.turn>=s.active.expires){const def=EVENTS.find(e=>e.id===s.active.id);if(def&&g.turn>=s.active.expires)note(g,r,def.id,def.title+' expired without a response.','expired');s.active=null;s.lastEvent=g.turn;}else if(!humanControlsRealm(g,r)&&g.turn>=(x.availableAt??x.started)){const choice=aiChoice(g,r,x);if(choice>=0&&!resolve(g,r,choice).ok){const alternative=choice===0?1:0;const c=x.choices[alternative];if(c&&applicable(g,r,x.target,c.effects)&&f.treasury>=c.cost)resolve(g,r,alternative);}}}
 if(!s.active&&g.turn-s.lastEvent>=9){const ctx=context(g,world,r),eligible=EVENTS.filter(e=>e.trigger!=='followup'&&!urgentTriggers.has(e.trigger)&&ctx[e.trigger]&&g.turn-(s.last[e.id]??-1000)>=72);if(eligible.length){const priority=eligible.filter(e=>!['land','army','vassal','neighbor'].includes(e.trigger)),firstRegional=eligible.filter(e=>e.trigger==='region_'+r&&s.last[e.id]===undefined),pool=g.turn>=12&&firstRegional.length?firstRegional:priority.length&&rand(root)<.75?priority:eligible,e=pool[Math.floor(rand(root)*pool.length)];s.active={id:e.id,target:ctx[e.trigger],started:g.turn,expires:g.turn+9};s.last[e.id]=g.turn;s.lastEvent=g.turn;if(r===g.player)note(g,r,e.id,'New event: '+e.title,'opened');}}
 // Up to two urgent situations can coexist with ordinary campaign content.
 for(const active of [...s.concurrent]){const x=eventView(g,r,active);if(!x||g.turn>=active.expires){s.concurrent=s.concurrent.filter(a=>a!==active);s.lastUrgent=g.turn;const def=EVENTS.find(e=>e.id===active.id);if(def&&g.turn>=active.expires)note(g,r,def.id,def.title+' expired without a response.','expired');continue;}if(!humanControlsRealm(g,r)&&g.turn>=(x.availableAt??x.started)){const choice=aiChoice(g,r,x);if(choice>=0)resolve(g,r,choice,x.id);}}
 if(s.concurrent.length<2&&g.turn-s.lastUrgent>=6){const ctx=context(g,world,r),eligible=EVENTS.filter(e=>urgentTriggers.has(e.trigger)&&ctx[e.trigger]&&g.turn-(s.last[e.id]??-1000)>=72&&!s.concurrent.some(a=>a.id===e.id||e.choices.some(c=>c.next===a.id)));if(eligible.length){const e=eligible.find(e=>e.trigger==='newReign')||eligible[0];s.concurrent.push({id:e.id,target:ctx[e.trigger],started:g.turn,expires:g.turn+9});s.last[e.id]=g.turn;s.lastUrgent=g.turn;note(g,r,e.id,'Urgent situation: '+e.title,'opened');}}
 if(!humanControlsRealm(g,r)&&g.turn%12===0&&f.treasury>900){const ds=expandedDecisions(g,world,r).filter(d=>d.ready&&d.trigger!=='land');if(ds.length)decide(g,world,r,ds[Math.floor(rand(root)*ds.length)].id);}
 }
 tickEmergent(g,world);
}
